{"hypothesis":"Replacing uniformly shuffled cut testing with coarse-to-fine refinement around promising cuts will locate a topology change whose repaired score improves the warm start by at least 1e-5.","rationale":"The parent spends its search budget testing unrelated cuts, although a useful packet rearrangement may require a precisely placed boundary. Keeping its scoring and packet-weight repair unchanged, this version reserves part of the search for multiscale refinement of the best cuts in each reflection mode.","source":"import time
import numpy as np
import scipy.fft as fft
from scipy.signal import oaconvolve
from scipy.optimize import minimize

PARAMS = {
    'search_fraction': (0.43, 0.15, 0.55),
    'total_fraction': (0.70, 0.50, 0.73),
    'repair_tolerance': (0.0003, 0.000001, 0.01, 'log'),
    'beta': (3e8, 1e6, 1e11, 'log'),
    'cuts': (36, 12, 120),
    'refinement_fraction': (0.45, 0.2, 0.7),
}


def decode(obj):
    if 'values' in obj:
        return np.maximum(np.asarray(obj['values'], dtype=float), 0.0)
    a = np.maximum(np.asarray(obj['ring'], dtype=float), 0.0)
    k = int(obj.get('cut', 0))
    mode = int(obj.get('reflection', 0))
    if mode == 1:
        return np.concatenate((a[:k][::-1], a[k:]))
    if mode == 2:
        return np.concatenate((a[:k], a[k:][::-1]))
    return np.concatenate((a[k:], a[:k])) if k else a.copy()


def exact_score(f):
    c = oaconvolve(f, f, mode='full')
    x = np.linspace(-0.5, 0.5, len(c) + 2)
    y = np.concatenate(([0.0], c, [0.0]))
    a, b = y[:-1], y[1:]
    num = float(np.sum((np.diff(x) / 3.0) * (a*a + a*b + b*b)))
    return float(num / ((np.sum(np.abs(c)) / (len(c)+1)) * np.max(np.abs(c))))


def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['total_fraction']) * budget_s
    search_end = start + float(params['search_fraction']) * budget_s
    coarse_end = start + float(params['search_fraction']) * (1-float(params['refinement_fraction'])) * budget_s
    if init is None:
        return {'values': [1.0]}
    f0 = decode(init)
    baseline = exact_score(f0)
    n = len(f0)
    if n < 4 or time.monotonic() >= deadline:
        return init
    rng = np.random.default_rng(seed)
    f0 = f0 / float(f0.max())
    m = fft.next_fast_len(2*n-1, real=True)
    best_score = baseline
    best_f = None
    contender = None
    contender_score = -np.inf
    observations = [{}, {}, {}]
    tested = set()

    def approximate(f):
        s = fft.rfft(f, m, workers=1)
        c = fft.irfft(s*s, m, workers=1)[:2*n-1]
        return float((2*np.dot(c, c) + np.dot(c[:-1], c[1:])) /
                     (3*np.sum(np.abs(c))*np.max(np.abs(c))))

    def make(k, mode):
        if mode == 0:
            return np.concatenate((f0[k:], f0[:k]))
        if mode == 1:
            return np.concatenate((f0[:k][::-1], f0[k:]))
        return np.concatenate((f0[:k], f0[k:][::-1]))

    def inspect(k, mode):
        nonlocal best_score, best_f, contender, contender_score
        k = int(k)
        if k <= 0 or k >= n or (k, mode) in tested or time.monotonic() >= search_end:
            return
        tested.add((k, mode))
        f = make(k, mode)
        score = approximate(f)
        observations[mode][k] = score
        if score > contender_score:
            contender_score = score
            contender = f
        if score > best_score - 2e-13 and time.monotonic() < deadline-1.0:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()

    cuts = set()
    cumulative = np.cumsum(f0)
    for q in np.linspace(0.01, 0.99, int(params['cuts'])):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(np.searchsorted(cumulative, q*cumulative[-1])))
    for d in np.geomspace(1, max(2, n//3), 18):
        if time.monotonic() >= coarse_end:
            break
        cuts.add(int(d))
        cuts.add(n-int(d))
    occupied = f0 > 0
    changes = np.flatnonzero(occupied[1:] != occupied[:-1]) + 1
    edges = np.r_[0, changes, n]
    widths = np.diff(edges)
    for j in np.argsort(widths)[::-1][:24]:
        if time.monotonic() >= coarse_end:
            break
        if not occupied[edges[j]]:
            cuts.add(int((edges[j]+edges[j+1])//2))
            cuts.add(int(edges[j]))
            cuts.add(int(edges[j+1]))
    jobs = [(k, mode) for k in sorted(cuts) if 0 < k < n for mode in (0, 1, 2)]
    rng.shuffle(jobs)
    for k, mode in jobs:
        if time.monotonic() >= coarse_end:
            break
        inspect(k, mode)

    # Refine the strongest cut basins separately in each adapter mode.
    # Boundaries of occupied runs are also offered as exact local proposals.
    radius = max(1, n//64)
    while time.monotonic() < search_end:
        proposed = []
        for mode in range(3):
            if time.monotonic() >= search_end:
                break
            ranked = sorted(observations[mode], key=observations[mode].get, reverse=True)
            centers = []
            for k in ranked:
                if time.monotonic() >= search_end:
                    break
                if all(abs(k-j) > radius for j in centers):
                    centers.append(k)
                    if len(centers) == 2:
                        break
            for k in centers:
                if time.monotonic() >= search_end:
                    break
                local = [k-radius, k+radius, k-radius//2, k+radius//2]
                p = int(np.searchsorted(changes, k))
                if p < len(changes):
                    local.append(int(changes[p]))
                if p:
                    local.append(int(changes[p-1]))
                for j in local:
                    if time.monotonic() >= search_end:
                        break
                    if 0 < j < n and (j, mode) not in tested:
                        proposed.append((j, mode))
        if not proposed:
            if radius == 1:
                break
            radius = max(1, radius//2)
            continue
        # Evaluate interleaved modes so no single reflection consumes a scale.
        rng.shuffle(proposed)
        for k, mode in proposed:
            if time.monotonic() >= search_end:
                break
            inspect(k, mode)
        radius = max(1, radius//2)

    def result():
        if best_f is None:
            return init
        return {'ring': best_f.tolist(), 'cut': 0, 'reflection': 0}

    if contender is None or contender_score < baseline-float(params['repair_tolerance']):
        return result()
    if time.monotonic() >= deadline-1.5:
        return result()
    base = contender
    spec = fft.rfft(base, m, workers=1)
    peak = fft.irfft(spec*spec, m, workers=1)[:2*n-1].max()
    base = base / np.sqrt(peak)
    indices = np.flatnonzero(base > 0)
    starts = np.r_[True, (np.diff(indices) != 1) | (indices[1:]//256 != indices[:-1]//256)]
    labels = np.cumsum(starts, dtype=np.int64)-1
    groups = int(labels[-1])+1
    active = base[indices]
    beta = float(params['beta'])

    class Stop(Exception):
        pass

    def objective(x):
        nonlocal best_score, best_f
        if time.monotonic() >= deadline-1.5:
            raise Stop()
        f = np.zeros(n)
        f[indices] = active*np.square(x[labels])
        sp = fft.rfft(f, m, workers=1)
        c = fft.irfft(sp*sp, m, workers=1)[:2*n-1]
        peak = c.max()
        e = np.exp(beta*(c-peak))
        z = e.sum()
        smooth = peak + np.log(z)/beta
        num = (2*np.dot(c,c)+np.dot(c[:-1],c[1:]))/3
        total = f.sum()
        quick = num/(np.sum(np.abs(c))*np.max(np.abs(c)))
        if quick > best_score+1e-13 and time.monotonic() < deadline-1.2:
            actual = exact_score(f)
            if actual > best_score:
                best_score = actual
                best_f = f.copy()
        if time.monotonic() >= deadline-1.0:
            raise Stop()
        g = 4*c
        g[1:] += c[:-1]
        g[:-1] += c[1:]
        g /= 3*num
        g -= e/(z*smooth)
        corr = fft.irfft(fft.rfft(g,m,workers=1)*np.conj(sp),m,workers=1)[:n]
        local = (2*corr[indices]-2/total)*active
        grad = 2*x*np.bincount(labels,weights=local,minlength=groups)
        value = np.log(num)-2*np.log(total)-np.log(smooth)
        return -value, -grad

    try:
        minimize(objective, np.ones(groups), jac=True, method='L-BFGS-B',
                 options={'maxcor': 7, 'maxiter': 10000, 'maxfun': 20000,
                          'ftol': 0.0, 'gtol': 0.0, 'maxls': 15})
    except Stop:
        pass
    return result()
"}
